def record(twin,index,state,values):
 if len(values)==10: values=values[:7]+['Collect discriminating diagnostic evidence']+values[7:]
 summary,symptom,evidence,cause,source,evidences,missing,action,remediation,abstain,reason,*esc=values; esc=esc[0] if esc else []
 a=resp(twin.upper(),symptom,summary,[evidence],[hyp(cause,state,evidences)],missing,action,EMPTY,remediation,abstain,reason,esc)
 user=f'Patch V3 {twin} {state} {index}: {summary} Evidence: {evidence} Determine the evidence state, safe next action, and required collaborator.'
 return {'messages':[{'role':'system','content':f'You are the {twin} Twin. Use structured-contract-v2. Distinguish supported from confirmed and require evidence before change.'},{'role':'user','content':user},{'role':'assistant','content':json.dumps(a,separators=(',',':'))}], 'metadata':{'patch':'EVIDENCE_STATE_V3','state':state,'crossDomain':bool(esc),'abstention':abstain},'provenance':{'domain':twin.upper(),'incidentId':f'V3-{twin.upper()}-{state}-{index}','incidentFamily':f'{twin}:evidence-state:{state.lower()}:{index}','mode':'SIMULATION','source':'EVIDENCE_STATE_PATCH_V3'},'trainingReady':False}
def split(rows):
 groups={}
 for r in rows: groups.setdefault(r['provenance']['incidentFamily'],[]).append(r)
 keys=sorted(groups); val={k for i,k in enumerate(keys) if i%5==0}; return [r for k in keys if k not in val for r in groups[k]],[r for k in keys if k in val for r in groups[k]]
