  answers=[r['messages'][-1]['content'] for r in rows]; prompts=[r['messages'][1]['content'] for r in rows]; lengths=[len(tok.apply_chat_template(r['messages'],tokenize=True,add_generation_prompt=False,enable_thinking=False)) for r in rows]
